function exposureCalc(port,dt){const fac=dfac(dt),base=fromIso(dt);
 const lines=DERIV_EXPO.filter(e=>!port||e.port===port).map(e=>{const pos=DERIV_POS.filter(p=>p.port===e.port&&p.sub===e.sub),cob=pos.filter(p=>p.prop==='Cobertura').reduce((a,p)=>a+p.noc,0)*fac,bruta=e.bruta*fac;return {port:e.port,sub:e.sub,bruta,cob,desc:bruta-cob,pct:bruta?cob/bruta:0,mtm:pos.reduce((a,p)=>a+p.mtm,0)*fac,n:pos.length}});
 const posRows=DERIV_POS.filter(p=>!port||p.port===port).map(p=>Object.assign({},p,{noc:p.noc*fac,mtm:p.mtm*fac,venc:base+p.rest*864e5}));
 const S1=(a,f)=>a.reduce((x,y)=>x+f(y),0),bruta=S1(lines,l=>l.bruta),cob=S1(lines,l=>l.cob);
 return {lines,posRows,bruta,cob,pct:bruta?cob/bruta:0,neta:bruta-cob,mtm:S1(posRows,p=>p.mtm),v30:S1(posRows.filter(p=>p.prop==='Cobertura'&&p.rest<=30),p=>p.noc),n30:posRows.filter(p=>p.prop==='Cobertura'&&p.rest<=30).length}}
function coverSVG(items){const W=1100,Hh=240,m={l:16,r:16,t:30,b:44},iw=W-m.l-m.r,ih=Hh-m.t-m.b,n=items.length,bw=iw/n*0.4;let mx=0;items.forEach(i=>{mx=Math.max(mx,i.cob+i.desc)});mx=mx||1;
 let g='<line x1="'+m.l+'" x2="'+(W-m.r)+'" y1="'+(Hh-m.b)+'" y2="'+(Hh-m.b)+'" stroke="currentColor" opacity=".4"/>';
 items.forEach((it,i)=>{const x=m.l+iw/n*i+(iw/n-bw)/2,hc=ih*it.cob/mx,hd=ih*it.desc/mx,y0=Hh-m.b;g+='<rect x="'+x+'" y="'+(y0-hc)+'" width="'+bw+'" height="'+Math.max(hc,1)+'" rx="3" fill="#6A1B9A"><title>Cubierto: '+f0(it.cob)+'</title></rect><rect x="'+x+'" y="'+(y0-hc-hd)+'" width="'+bw+'" height="'+Math.max(hd,1)+'" rx="3" fill="#94A3B8"><title>Descubierto: '+f0(it.desc)+'</title></rect><text x="'+(x+bw/2)+'" y="'+(y0-hc-hd-8)+'" text-anchor="middle" class="chart-txt" style="font-weight:600">'+pct(it.cob/(it.cob+it.desc||1),1)+' cubierto</text><text x="'+(x+bw/2)+'" y="'+(Hh-m.b+20)+'" text-anchor="middle" class="chart-txt">'+esc(it.l)+'</text>'});
 return '<svg viewBox="0 0 '+W+' '+Hh+'" width="100%" style="display:block;max-height:250px" role="img" aria-label="Cubierto y descubierto por subyacente">'+g+'</svg><div class="lgd"><span><i style="background:#6A1B9A"></i>Cubierto</span><span><i style="background:#94A3B8"></i>Descubierto</span></div>'}
