function inmMetrics(port,per){const k=PERIODS[per].k;return INSTRUMENTS.filter(a=>a.clase==='Inmueble'&&a.port===port).map(a=>{const v=assetVal(a),rr=rng(hash(a.mnem+per)),renta=(0.0040+rr()*0.0014)*k,sorted=a.avaluos.slice().sort((x,y)=>y.fecha-x.fecha),val=sorted.length>1?(sorted[0].valor-sorted[1].valor)/sorted[1].valor*Math.min(1,k):0;return {a,port,valor:v.valor,renta,val,total:renta+val}})}
function altMetrics(port){return INSTRUMENTS.filter(a=>a.clase&&a.clase!=='Renta fija'&&a.clase!=='Inmueble'&&a.port===port&&a.comp!=null).map(a=>{const v=assetVal(a),distrib=a.flujoEsp*(a.etapa==='Operativa'?5.2:1.4),moic=(v.valor+distrib)/a.desemb,years=Math.max(0.6,(fromIso(OPDATE)-a.emi)/(365*864e5)),tir=Math.pow(moic,1/years)-1;return {a,port,desemb:a.desemb,valor:v.valor,distrib,moic,tir,years}})}
