function wizard(name){
 const st={step:0,port:'Todos',d1:'2026-01-01',d2:'2026-09-30',fmt:'Excel',p:0},steps=[['Parámetros','Portafolio y periodo'],['Revisión','Confirma los datos'],['Generación','Preparando el archivo']];
 const m=openModal({title:'Generar reporte',cls:'mk-modal--wizard',sticky:true,sub:esc(name),body:'',foot:''});
 const wiz=()=>'<div class="mk-wizsteps">'+steps.map((s,i)=>(i?'<div class="mk-wizline'+(i<=st.step?' done':'')+'"></div>':'')+'<div class="mk-wizstep'+(i===st.step?' on':i<st.step?' done':'')+'"><div class="mk-wizstep__n">'+(i<st.step?'✓':i+1)+'</div><div class="mk-wizstep__t">'+s[0]+'</div><div class="mk-wizstep__d">'+s[1]+'</div></div>').join('')+'</div>';
 const render=()=>{let b='',ft='';
  if(st.step===0){b=wiz()+'<div class="mk-wizpanel"><div class="mk-formgrid">'+selF('w-port','Portafolio',['Todos'].concat(FUNDS),st.port,{req:true})+rangeFields(st.d1,st.d2,'el período del reporte','w-')+radiosF('w-fmt','Formato',['Excel','CSV'],st.fmt)+'</div></div>';ft='<div class="mk-wizfoot" style="width:100%;padding:0"><button class="mk-btn mk-btn--secondary" data-c>Cancelar</button><button class="mk-btn" data-n>Siguiente</button></div>'}
  else if(st.step===1){b=wiz()+'<div class="mk-wizpanel"><div class="mk-formgrid">'+fdRow('Reporte',esc(name))+fdRow('Portafolio',esc(st.port))+fdRow('Periodo',fmtD(fromIso(st.d1))+' – '+fmtD(fromIso(st.d2)))+fdRow('Formato',st.fmt)+'</div></div><div class="mk-mt">'+alertB('info','','Revisa los parámetros. El archivo se descargará en tu equipo.')+'</div>';ft='<div class="mk-wizfoot" style="width:100%;padding:0"><button class="mk-btn mk-btn--secondary" data-b>Atrás</button><button class="mk-btn" data-n>Generar</button></div>'}
  else{b=wiz()+'<div class="mk-wizpanel"><div class="mk-progress"><div class="mk-progress__bar" style="width:'+st.p+'%"></div></div><p class="mk-help mk-mt">'+(st.p<100?'Generando el reporte… '+st.p+'%':'Reporte listo para descargar.')+'</p></div>';ft=st.p<100?'<button class="mk-btn" disabled>Generando…</button>':'<button class="mk-btn mk-btn--secondary" data-c>Cerrar</button><button class="mk-btn" data-d>'+ic('download')+'Descargar</button>'}
  m.body.innerHTML=b;m.foot.innerHTML=ft;
  $$('[name="w-port"]',m.el).forEach(s=>s.addEventListener('change',()=>st.port=s.value));$$('[name="w-d1"],[name="w-d2"]',m.el).forEach(s=>s.addEventListener('change',()=>{st[s.name==='w-d1'?'d1':'d2']=s.value}));$$('[name="w-fmt"]',m.el).forEach(s=>s.addEventListener('change',()=>st.fmt=s.value));
 };
 m.el.addEventListener('click',e=>{
  if(e.target.closest('[data-c]')){m.close();return}
  if(e.target.closest('[data-b]')){st.step--;render();return}
  if(e.target.closest('[data-n]')){if(st.step===0&&!st.port){toast('Selecciona un portafolio.','warning');return}if(st.step===0&&(!st.d1||!st.d2||st.d1>st.d2)){toast('Revisa el rango: la fecha inicial debe ser igual o anterior a la final.','warning','Rango de fechas');return}st.step++;if(st.step===2){st.p=0;render();const t=setInterval(()=>{st.p=Math.min(100,st.p+20);if(!m.el.isConnected){clearInterval(t);return}render();if(st.p>=100)clearInterval(t)},350)}else render();return}
  if(e.target.closest('[data-d]')){const ds=reportData(name,st),base=name.replace(/[^\w]+/g,'-').toLowerCase()+'-'+new Date().toISOString().slice(0,10);exportTable(base,st.fmt==='Excel'?'xlsx':'csv',ds.heads,ds.rows,'Reporte');toast(esc(name),'success','Reporte descargado');m.close()}
 });
 render();
}


