 pg.innerHTML='<div class="mk-subhead">'+ic('flows')+'Ciclo de vida de una orden</div><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:stretch">'+box(ST[0])+arrow('→')+box(ST[1])+arrow('→')+box(ST[2])+'</div><div style="display:flex;gap:12px;margin-top:12px;align-items:center;flex-wrap:wrap"><span class="mk-help">Desde Registrada o Complementación también se puede anular:</span>'+arrow('→')+'<div style="width:260px">'+box(ST[3],200)+'</div></div><div class="mk-subhead mk-mt">'+ic('check')+'Acciones permitidas por estado</div><div id="ft"></div>';
